export function mediaRelease(verified,baseNodeIds){
 const existing=new Set(baseNodeIds),nodes=mediaNodes.filter(n=>!existing.has(n.id)&&n.sourceIds.every(id=>verified.has(id))).map(n=>({...n})),ids=new Set([...existing,...nodes.map(n=>n.id)]);
 const edges=mediaEdges.filter(e=>e.sourceIds.every(id=>verified.has(id))&&ids.has(e.source)&&ids.has(e.target));
 return {nodes,edges,complete:mediaSources.every(s=>verified.has(s.id))};
}
